package cc.ataglace.molebutter.marketplacelotteon.internal.product;
import java.util.*;import org.springframework.stereotype.Component;import tools.jackson.databind.ObjectMapper;
import cc.ataglace.molebutter.marketplace.api.*;import cc.ataglace.molebutter.marketplace.api.MarketplaceDrafts.*;import cc.ataglace.molebutter.marketplace.api.MarketplaceWriteGateway.*;import cc.ataglace.molebutter.media.api.*;
import static cc.ataglace.molebutter.marketplace.api.PartnerFormSupport.*;
@Component final class LotteonDocuments implements StandaloneProductDocuments {
 final LotteonCatalog catalog;final ObjectMapper json;LotteonDocuments(LotteonCatalog catalog,ObjectMapper json){this.catalog=catalog;this.json=json;}
 public String market(){return "LOTTEON";}public String accountKey(){return catalog.client.account();}public boolean supports(Document d){return d.markets().containsKey(Market.LOTTEON);}
 public Document normalize(Document d){var i=LotteonInput.get(d);return i==null?d:LotteonInput.with(d,LotteonInput.structure(i),state(d));}
 static EditorState state(Document d){var c=d.markets().get(Market.LOTTEON);return c==null||c.lotteon()==null?null:c.lotteon().editorState();}
 public Document newDocument(Document d){d=MarketplaceDocuments.normalize(d);var previous=LotteonInput.get(d);var state=state(d);if(previous!=null&&state==null)return normalize(d);if(previous!=null&&previous.deliveryIntent()==null&&state!=null){var overrides=new ArrayList<>(state.overrides());if(!overrides.contains("deliveryIntent"))overrides.add("deliveryIntent");state=new EditorState(state.version(),List.copyOf(overrides),state.pricing(),state.optionStructure(),state.imageSource(),state.imageOptionId(),state.descriptionSource(),state.descriptionOptionId(),state.unmapped());}var base=fromCommon(d,LotteonProductMapping.COMMON,LotteonProductMapping.DEFAULTS);var fields=new LinkedHashMap<String,Object>(base.fields());fields.putAll(MarketplaceCommonSettings.partnerFields("LOTTEON",d));var c=d.markets().get(Market.LOTTEON);fields.put("scatNo",c.categoryCode());if(c.addressBook()!=null){if(c.addressBook().outbound()!=null)fields.put("owhpNo",c.addressBook().outbound().code());if(c.addressBook().returns()!=null)fields.put("rtrpNo",c.addressBook().returns().code());}if(c.lotteon()!=null&&c.lotteon().brandId()!=null)fields.put("brdNo",c.lotteon().brandId());fields.put("sitmYn",d.options().size()==1&&d.options().getFirst().attributes().isEmpty()?"N":"Y");var sharedItems=new LinkedHashMap<String,LotteonInput.Item>();for(var option:d.options()){var own=d.media().images().stream().filter(v->option.id().equals(v.optionId())).map(v->new LotteonInput.Picture(new PartnerEditor.Image(v.id(),v.assetId(),v.url(),v.representative(),v.order()),"IMG_SQRE")).toList();if(!own.isEmpty())sharedItems.put(option.id(),new LotteonInput.Item(List.of(),own));}var nativeInput=new LotteonInput(new PartnerEditor.Input(fields,base.options(),base.images(),base.description(),base.noticeType(),base.notices(),base.certifications()),List.of(),Map.copyOf(sharedItems),base.options().isEmpty()?null:base.options().getFirst().id(),Map.of(),LotteonInput.commonDelivery(d));
  if(previous!=null){var desired=new LinkedHashMap<String,Object>(LotteonInput.parts(nativeInput));var before=LotteonInput.parts(previous);var changes=new ArrayList<MarketplaceEditing.Change>();var overrides=state==null?List.<String>of():state.overrides();for(var e:before.entrySet())if(e.getKey().startsWith("product.fields.")&&!desired.containsKey(e.getKey())||overrides.contains(e.getKey())||Set.of("attributes","product.noticeType","product.notices","product.certifications").contains(e.getKey())||e.getKey().startsWith("items.")&&e.getKey().endsWith(".attributes"))changes.add(new MarketplaceEditing.Change("lotteon."+e.getKey(),null,e.getValue()));var projected=nativeInput;var old=previous;var rows=projected.product().options().stream().map(row->{var prior=old.product().options().stream().filter(v->v.id().equals(row.id())).findFirst().orElse(null);if(prior==null)return row;String prefix="product.options."+row.id()+".";return new PartnerEditor.Option(row.id(),overrides.contains(prefix+"name")?prior.name():row.name(),overrides.contains(prefix+"sku")?prior.sku():row.sku(),overrides.contains(prefix+"price")?prior.price():row.price(),overrides.contains(prefix+"quantity")?prior.quantity():row.quantity(),overrides.contains(prefix+"attributes")?prior.attributes():row.attributes(),overrides.contains(prefix+"usable")?prior.usable():row.usable());}).toList();var p=projected.product();nativeInput=new LotteonInput(new PartnerEditor.Input(p.fields(),rows,p.images(),p.description(),p.noticeType(),p.notices(),p.certifications()),projected.attributes(),projected.items(),projected.representativeOptionId(),projected.status(),projected.deliveryIntent());
   var optionIds=rows.stream().map(PartnerEditor.Option::id).collect(java.util.stream.Collectors.toSet());changes=changes.stream().filter(change->(!change.path().startsWith("lotteon.items.")||optionIds.contains(change.path().substring(14).split("\\.")[0]))&&(!change.path().startsWith("lotteon.product.options.")||optionIds.contains(change.path().substring(24).split("\\.")[0]))).collect(java.util.stream.Collectors.toCollection(ArrayList::new));nativeInput=LotteonInput.apply(nativeInput,changes,json);}
  return LotteonInput.with(d,nativeInput,state==null?new EditorState(1,List.of(),"COMMON","COMMON",null,null,null,null,List.of()):state);
 }
 public Observed standalone(Long actor,String product){catalog.schema(actor);var s=catalog.snapshot(product);var d=projection(s.input());d=restricted(d,s.supported());return new Observed(d,new Mapping(accountKey(),product,s.observation().identities().stream().map(v->new OptionMapping(v.optionId(),v.remoteId(),null)).toList()));}
 private Document projection(LotteonInput i){var p=i.product();var bounded=new PartnerEditor.Input(p.fields(),p.options().stream().limit(200).toList(),p.images(),p.description(),p.noticeType(),p.notices(),p.certifications());return LotteonInput.with(PartnerFormSupport.document(market(),bounded,List.of(Market.LOTTEON),LotteonProductMapping.COMMON),i,null);}
 public Document observe(Long actor,Document reference,Mapping mapping){catalog.schema(actor);if(!accountKey().equals(mapping.accountKey()))throw invalid("롯데ON 연결 계정이 변경되었습니다.");var s=catalog.snapshot(mapping.sellerProductId());var ids=new LinkedHashMap<String,String>();for(var i:s.observation().identities()){var row=mapping.options().stream().filter(v->v.sellerProductItemId().equals(i.remoteId())).findFirst().orElseThrow(()->invalid("롯데ON 단품 구성이 변경되었습니다. 다시 연결해 주세요."));ids.put(i.optionId(),row.optionId());}if(ids.size()!=mapping.options().size())throw invalid("롯데ON 단품 구성이 변경되었습니다.");return restricted(LotteonInput.with(reference,LotteonProductMapping.remap(s.input(),ids),null),s.supported());}
 private Document restricted(Document d,boolean supported){return LotteonInput.with(d,LotteonInput.get(d),supported?null:new EditorState(1,List.of(),"CUSTOM","CUSTOM",null,null,null,null,List.of("READ_ONLY_PRODUCT")));}
 public String readOnlyReason(Document d){var state=state(d);return state!=null&&state.unmapped()!=null&&state.unmapped().contains("READ_ONLY_PRODUCT")?"미승인·반려·특수 상품 또는 옵션 200개 초과 상품은 조회만 지원합니다.":null;}
 public boolean supportsPendingEdits(){return true;}
 public MarketplaceEditing.PendingRebase rebase(Document a,Document b,List<MarketplaceEditing.Change> changes){return LotteonInput.rebase(LotteonInput.get(a),LotteonInput.get(b),changes,json);}
 public Document apply(Document d,List<MarketplaceEditing.Change> changes){var before=LotteonInput.get(d);var after=LotteonInput.apply(before,changes,json);var state=state(d);if(state!=null){var overrides=new LinkedHashSet<String>(state.overrides());for(var c:LotteonInput.diff(before,after,json)){if(c.path().equals("lotteon.product.options")){for(var row:after.product().options()){var old=before.product().options().stream().filter(v->v.id().equals(row.id())).findFirst().orElse(null);if(old!=null){var a=json.valueToTree(old);var b=json.valueToTree(row);for(String field:List.of("name","sku","price","quantity","attributes","usable"))if(!a.path(field).equals(b.path(field)))overrides.add("product.options."+row.id()+"."+field);}}}else overrides.add(c.path().substring(8));}state=new EditorState(1,List.copyOf(overrides),state.pricing(),state.optionStructure(),state.imageSource(),state.imageOptionId(),state.descriptionSource(),state.descriptionOptionId(),state.unmapped());}return LotteonInput.with(d,after,state);}
 public List<MarketplaceEditing.Change> comparisonFields(Document d){return LotteonInput.parts(LotteonInput.get(d)).entrySet().stream().filter(e->!e.getKey().equals("product.options")).map(e->new MarketplaceEditing.Change("lotteon."+e.getKey(),null,e.getValue())).toList();}
 public Document saveTarget(Document reference,Document desired){return LotteonInput.with(reference,LotteonInput.get(desired),state(desired));}
 public void validateSettings(Long actor,Document d,boolean create,List<MarketplaceEditing.Change> changes){if(!create&&changes.stream().anyMatch(c->c.path().equals("lotteon.deliveryIntent")||c.path().equals("lotteon.product.fields.dvCstPolNo")))LotteonDeliveryPolicy.verify(actor,catalog,LotteonInput.get(d));}
 public void validate(Long actor,Document d,boolean create){catalog.schema(actor);if(create){MarketplaceCommonSettings.validate(d);LotteonDeliveryPolicy.verify(actor,catalog,LotteonInput.get(d));}if(readOnlyReason(d)!=null)throw invalid(readOnlyReason(d));LotteonProductMapping.validateNative(LotteonInput.get(d),create);LotteonProductMapping.validateMedia(LotteonInput.get(d));}
 public List<ImageInspection.Input> images(Document d,Set<String> existing){var nativeInput=LotteonInput.get(d);var images=new ArrayList<ImageInspection.Input>();if(nativeInput==null)return images;for(var o:nativeInput.product().options())for(var pic:LotteonProductMapping.images(nativeInput,o.id())){var i=pic.image();String role=pic.type().equals("IMG_SQRE")?(i.representative()?"REPRESENTATION":"DETAIL"):(i.representative()?"REPRESENTATION_PORTRAIT":"DETAIL_PORTRAIT");images.add(new ImageInspection.Input(market(),role,o.id(),i.id(),i.url(),i.assetId(),existing.contains(i.url())));}images.addAll(ImageInspection.descriptionInputs(market(),nativeInput.product().description(),null).stream().map(i->new ImageInspection.Input(i.market(),i.role(),i.optionId(),i.imageId(),i.url(),i.assetId(),existing.contains(i.url()))).toList());return List.copyOf(images);}
 public Document commonReference(Document d){if(readOnlyReason(d)!=null)throw invalid(readOnlyReason(d));var i=LotteonInput.get(d);if(i.product().options().size()>200)throw invalid("앱 편집·연결 제한: 공통 옵션은 200개 이하입니다.");var common=projection(i);var pics=new ArrayList<MarketplaceDrafts.Image>(common.media().images());for(var o:i.product().options()){var own=i.items().get(o.id());if(own!=null)for(var p:own.images()){var v=p.image();pics.add(new MarketplaceDrafts.Image(v.id(),v.assetId(),v.url(),v.representative(),v.order(),o.id()));}}return new Document(d.id(),d.revision(),common.common(),common.options(),common.stockMode(),common.productQuantity(),common.services(),new Media(pics,common.media().contents()),d.delivery(),d.selectedMarkets(),d.markets());}
}
